def best_of_n(candidates: list, scores: list) -> str:
    """Return the candidate with the highest score; ties keep the earliest candidate."""
    best_idx = 0
    for i in range(1, len(scores)):
        if scores[i] > scores[best_idx]:
            best_idx = i
    return candidates[best_idx]

print(best_of_n(['ans1', 'ans2', 'ans3'], [0.62, 0.91, 0.77]))

def score_gain(scores: list) -> float:
    """Best score minus the average score, rounded to 2 decimals."""
    best = max(scores)
    avg = sum(scores) / len(scores)
    return round(best - avg, 2)

print(score_gain([0.62, 0.91, 0.77]))
